// Loads the Hastea wasm module in the browser.
//
// GHC's wasm backend emits a WASI reactor module plus a small JS file
// (ghc_wasm_jsffi.js, generated by post-link.mjs) that provides the
// JavaScript FFI imports. A WASI shim supplies the system-call layer; it is
// bundled with the hastea command (see hastea-cli/runtime/), so the page
// needs no other host.
import {
  WASI,
  OpenFile,
  File,
  ConsoleStdout,
} from "./browser_wasi_shim.js";
import ghc_wasm_jsffi from "./ghc_wasm_jsffi.js";

const wasi = new WASI([], [], [
  new OpenFile(new File([])), // stdin
  ConsoleStdout.lineBuffered((msg) => console.log(msg)), // stdout
  ConsoleStdout.lineBuffered((msg) => console.warn(msg)), // stderr
]);

// ghc_wasm_jsffi needs the module's exports, which only exist after
// instantiation, so we fill this object in afterwards.
const exports = {};

const { instance } = await WebAssembly.instantiateStreaming(
  fetch("hastea.wasm"),
  {
    wasi_snapshot_preview1: wasi.wasiImport,
    ghc_wasm_jsffi: ghc_wasm_jsffi(exports),
  },
);
Object.assign(exports, instance.exports);

wasi.initialize(instance);
await instance.exports.hs_start();
